const PROJECT = '964775386a3ce03ecca883.03770715';
const cfg = $('Config').all();
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const meta = (cfg[i] && cfg[i].json) ? cfg[i].json : {};
  let b64 = '';
  let how = '';
  try {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    b64 = buf.toString('base64');
    how = 'helper';
  } catch (e) {
    const bin = (it.binary || {}).data;
    b64 = (bin && bin.data) ? bin.data : '';
    how = 'inline';
  }
  out.push({ json: {
    name: meta.name,
    title: meta.title,
    how: how,
    bytes: b64.length,
    url: 'https://api.lokalise.com/api2/projects/' + PROJECT + '/screenshots',
    body: { screenshots: [{ data: 'data:image/png;base64,' + b64, title: meta.title, description: 'RealChecker Figma - Ready for Dev / VIN Number Lookup', ocr: true, key_ids: [] }] }
  }});
}
return out;

const reqs = $('Build Upload Payload').all();
const res = $input.all();
const rows = [];
for (let i = 0; i < res.length; i++) {
  const r = res[i].json || {};
  const meta = (reqs[i] && reqs[i].json) ? reqs[i].json : {};
  const body = r.body || {};
  const shots = body.screenshots || [];
  rows.push({ name: meta.name, title: meta.title, bytes: meta.bytes, status: r.statusCode, screenshot_id: shots.length ? shots[0].screenshot_id : null, error: shots.length ? null : JSON.stringify(body).slice(0, 200) });
}
return [{ json: { uploaded: rows.filter(function (x) { return x.screenshot_id; }).length, total: rows.length, rows: rows } }];
